local SackLoaderMaker = {}
local PRODUCTS = {
    iron_sack_loader = { name = "Železni nalagalec vrečk", ironCost = 2, woodCost = 3, leatherCost = 2, time = 5, cost = 150, prestige = 3, happiness = 2, description = "Železni nalagalec za vreče z žitom." },
    bronze_sack_loader = { name = "Bronast nalagalec vrečk", bronzeCost = 2, ironCost = 1, woodCost = 3, leatherCost = 2, time = 7, cost = 365, prestige = 5, happiness = 3, description = "Bronast nalagalec za mline." },
    silver_sack_loader = { name = "Srebrni nalagalec vrečk", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 2, time = 11, cost = 880, prestige = 10, happiness = 4, description = "Srebrni nalagalec za plemiške mline." },
    gilded_sack_loader = { name = "Pozlačeni nalagalec vrečk", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 2, time = 15, cost = 1900, prestige = 19, happiness = 5, description = "Pozlačeni nalagalec za dvorne mline." },
    jewel_set_sack_loader = { name = "Draguljasti nalagalec vrečk", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 2, time = 19, cost = 4100, prestige = 35, happiness = 7, description = "Draguljasti nalagalec za kraljeve mline." },
    royal_sovereign_sack_loader = { name = "Kraljevski suvereni nalagalec vrečk", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 2, time = 26, cost = 8800, prestige = 67, happiness = 13, description = "Suvereni nalagalec z biseri za krono." },
}
local BUILDINGS = {
    sackloader_workshop = { name = "Nalagalna delavnica", cost = { gold = 310, wood = 180, stone = 125, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    sackloader_house = { name = "Nalagalna hiša", cost = { gold = 1150, wood = 360, stone = 260, silver = 6, iron = 6 }, upkeep = 24, qualityBonus = 18 },
    master_sackloader_atelier = { name = "Mojstrski nalagalni atelje", cost = { gold = 2920, wood = 420, stone = 505, silver = 34, gold = 7 }, upkeep = 69, qualityBonus = 30 },
    sovereign_sackloader_palace = { name = "Suverena nalagalna palača", cost = { gold = 12650, wood = 640, stone = 815, gold = 81, jewel = 18 }, upkeep = 248, qualityBonus = 55, prestigeBonus = 50 },
}
SackLoaderMaker.ironStock = 12; SackLoaderMaker.bronzeStock = 10; SackLoaderMaker.woodStock = 16; SackLoaderMaker.leatherStock = 12; SackLoaderMaker.silverStock = 8; SackLoaderMaker.goldStock = 6; SackLoaderMaker.jewelStock = 4; SackLoaderMaker.pearlStock = 4
SackLoaderMaker.productStock = {}; SackLoaderMaker.buildings = {}; SackLoaderMaker.maker = nil; SackLoaderMaker.activeMaking = {}; SackLoaderMaker.totalProducts = 0; SackLoaderMaker.dayTimer = 0
function SackLoaderMaker.init() SackLoaderMaker.ironStock=12; SackLoaderMaker.bronzeStock=10; SackLoaderMaker.woodStock=16; SackLoaderMaker.leatherStock=12; SackLoaderMaker.silverStock=8; SackLoaderMaker.goldStock=6; SackLoaderMaker.jewelStock=4; SackLoaderMaker.pearlStock=4; SackLoaderMaker.productStock={}; SackLoaderMaker.buildings={}; SackLoaderMaker.maker=nil; SackLoaderMaker.activeMaking={}; SackLoaderMaker.totalProducts=0; SackLoaderMaker.dayTimer=0; print("[SackLoaderMaker] Royal Sack Loader Maker System initialized (6 products, 4 buildings)") end
function SackLoaderMaker.hireMaker(n,s) s=s or math.random(55,90); local c=565+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SackLoaderMaker.maker={name=n or ("Nalagalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Nalagalec najet: %s (spretnost: %d)",SackLoaderMaker.maker.name,s),"success") end; return true end
function SackLoaderMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SackLoaderMaker.build(id) local ok,e=SackLoaderMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SackLoaderMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SackLoaderMaker.getQualityBonus() local b=0; for _,bd in ipairs(SackLoaderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SackLoaderMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SackLoaderMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SackLoaderMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SackLoaderMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SackLoaderMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SackLoaderMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SackLoaderMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SackLoaderMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SackLoaderMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SackLoaderMaker.buildings==0 then return false,"Potrebna nalagalna delavnica" end; if not SackLoaderMaker.maker then return false,"Potreben nalagalec" end; return true end
function SackLoaderMaker.make(pt,qty) qty=qty or 1; local ok,e=SackLoaderMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SackLoaderMaker.ironStock=SackLoaderMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SackLoaderMaker.bronzeStock=SackLoaderMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SackLoaderMaker.woodStock=SackLoaderMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SackLoaderMaker.leatherStock=SackLoaderMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SackLoaderMaker.silverStock=SackLoaderMaker.silverStock-d.silverCost*qty end; if d.goldCost then SackLoaderMaker.goldStock=SackLoaderMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SackLoaderMaker.jewelStock=SackLoaderMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SackLoaderMaker.pearlStock=SackLoaderMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SackLoaderMaker.maker then t=math.max(1,t-math.floor(SackLoaderMaker.maker.skill/13)) end; table.insert(SackLoaderMaker.activeMaking,{id="sackloader_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SackLoaderMaker.completeMaking(m) local q=1.0+(SackLoaderMaker.getQualityBonus()/100); if SackLoaderMaker.maker then q=q+(SackLoaderMaker.maker.skill/140) end; q=math.min(2.5,q); SackLoaderMaker.productStock[m.productType]=(SackLoaderMaker.productStock[m.productType] or 0)+m.quantity; SackLoaderMaker.totalProducts=SackLoaderMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SackLoaderMaker.maker then SackLoaderMaker.maker.itemsMade=SackLoaderMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SackLoaderMaker.maker.skill=math.min(100,SackLoaderMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Nalagalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sackloader.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function SackLoaderMaker.update(dt) if not _G.state then return end; SackLoaderMaker.dayTimer=SackLoaderMaker.dayTimer+dt; if SackLoaderMaker.dayTimer>=30 then SackLoaderMaker.dayTimer=0; for i=#SackLoaderMaker.activeMaking,1,-1 do local m=SackLoaderMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SackLoaderMaker.completeMaking(m); table.remove(SackLoaderMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SackLoaderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SackLoaderMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SackLoaderMaker.getStats() return {ironStock=SackLoaderMaker.ironStock,bronzeStock=SackLoaderMaker.bronzeStock,woodStock=SackLoaderMaker.woodStock,leatherStock=SackLoaderMaker.leatherStock,silverStock=SackLoaderMaker.silverStock,goldStock=SackLoaderMaker.goldStock,jewelStock=SackLoaderMaker.jewelStock,pearlStock=SackLoaderMaker.pearlStock,productStock=SackLoaderMaker.productStock,numBuildings=#SackLoaderMaker.buildings,hasMaker=SackLoaderMaker.maker~=nil,makerName=SackLoaderMaker.maker and SackLoaderMaker.maker.name or "—",makerSkill=SackLoaderMaker.maker and SackLoaderMaker.maker.skill or 0,activeMaking=#SackLoaderMaker.activeMaking,totalProducts=SackLoaderMaker.totalProducts} end
return SackLoaderMaker
